// HTTP/HTTPS through the system libraries (libSceNet + libSceSsl + libSceHttp), following the
// init order of the OpenOrbis net_http sample. Unlike the sample we do NOT install an SSL callback
// that accepts every certificate: the system's default server verification stays on.
// Old firmware carries an outdated root list, so modern sites fail verification (0x8095F00C on send,
// seen on the console with 01.07). We add current roots (ca_roots.inc, generated by
// tools/make_ca_roots.py from the Mozilla store) with sceHttpsLoadCert. Verification is never disabled.
// Status: compiles for PS4; root loading not yet tested on a console.
#include <orbis/Http.h>
#include <orbis/Net.h>
#include <orbis/Ssl.h>
#include <orbis/Sysmodule.h>

#include <cstring>

#include "platform/ps4/ps4_platform.hpp"

namespace ml::ps4 {

namespace {
constexpr const char *kUserAgent = "MoonlightHB/1.0 (PlayStation 4)";

struct Request {
    int tpl = -1, conn = -1, req = -1;
    ~Request()
    {
        if (req >= 0) sceHttpDeleteRequest(req);
        if (conn >= 0) sceHttpDeleteConnection(conn);
        if (tpl >= 0) sceHttpDeleteTemplate(tpl);
    }
};

std::string hex(int v)
{
    char b[16];
    std::snprintf(b, sizeof b, "0x%08X", unsigned(v));
    return b;
}

#include "ca_roots.inc"

// Plain arrays without constructors (no static initialisers in the PS4 binary). They stay alive for the
// whole run because we do not know whether libSceHttp copies them.
SslPem gCaRecs[ML_CA_ROOT_COUNT];
const SslPem *gCaPtrs[ML_CA_ROOT_COUNT];

// Returns a short report for "Testar internet".
std::string loadRoots(int ctx)
{
    for (int i = 0; i < ML_CA_ROOT_COUNT; ++i) {
        gCaRecs[i].ptr = const_cast<char *>(kCaRoots[i]);
        gCaRecs[i].size = kCaRootSizes[i];
        gCaPtrs[i] = &gCaRecs[i];
    }
    int r = sceHttpsLoadCert(ctx, ML_CA_ROOT_COUNT, (void *)gCaPtrs, nullptr, nullptr);
    if (r >= 0) return std::to_string(ML_CA_ROOT_COUNT) + " certificados raiz atuais carregados";
    // Some firmware may reject ECC roots: retry with the RSA ones only (they come first).
    int r2 = sceHttpsLoadCert(ctx, ML_CA_ROOT_RSA_COUNT, (void *)gCaPtrs, nullptr, nullptr);
    if (r2 >= 0) return std::to_string(ML_CA_ROOT_RSA_COUNT) + " certificados raiz RSA carregados (todos: " + hex(r) + ")";
    return "certificados raiz nao carregaram (" + hex(r) + " / " + hex(r2) + ")";
}

class Ps4Stream : public HttpStream {
public:
    std::unique_ptr<Request> r;
    int code = 0;
    std::string ctype;
    long read(void *buf, size_t len) override
    {
        int n = sceHttpReadData(r->req, buf, uint32_t(len > 0x7FFFFFFF ? 0x7FFFFFFF : len));
        return n < 0 ? -1 : long(n);
    }
    int status() const override { return code; }
    std::string contentType() const override { return ctype; }
};
}  // namespace

// Same order and pool sizes as the OpenOrbis net_http sample. Each step's code is reported so a failure
// on the console says exactly where it stopped (Configuracoes -> Testar internet).
bool Http::init(std::string *err)
{
    int r = sceSysmoduleLoadModuleInternal(ORBIS_SYSMODULE_INTERNAL_NET);
    if (r < 0) { *err = "carregar modulo NET " + hex(r); return false; }
    r = sceSysmoduleLoadModuleInternal(ORBIS_SYSMODULE_INTERNAL_HTTP);
    if (r < 0) { *err = "carregar modulo HTTP " + hex(r); return false; }
    r = sceSysmoduleLoadModuleInternal(ORBIS_SYSMODULE_INTERNAL_SSL);
    if (r < 0) { *err = "carregar modulo SSL " + hex(r); return false; }
    if (netPool_ < 0) {
        sceNetInit();
        int net = sceNetPoolCreate("ml_net", 4 * 1024, 0);
        if (net < 0) { *err = "sceNetPoolCreate " + hex(net); return false; }
        netPool_ = net;
    }
    if (ssl_ < 0) {
        int ssl = sceSslInit(SSL_POOLSIZE);
        if (ssl < 0) { *err = "sceSslInit " + hex(ssl); return false; }
        ssl_ = ssl;
    }
    if (ctx_ < 0) {
        int http = sceHttpInit(netPool_, ssl_, LIBHTTP_POOLSIZE);
        if (http < 0) { *err = "sceHttpInit " + hex(http); return false; }
        ctx_ = http;
        certInfo_ = loadRoots(ctx_);
    }
    return true;
}

// Creates template/connection/request, sends it, and fills status. Returns "" or an error.
static std::string begin(int ctx, const HttpRequest &q, Request &r, int &status)
{
    r.tpl = sceHttpCreateTemplate(ctx, kUserAgent, ORBIS_HTTP_VERSION_1_1, 1);
    if (r.tpl < 0) return "template " + hex(r.tpl);
    uint32_t us = uint32_t(q.timeoutMs) * 1000u;
    sceHttpSetConnectTimeOut(r.tpl, us);
    sceHttpSetResolveTimeOut(r.tpl, us);
    sceHttpSetSendTimeOut(r.tpl, us);
    r.conn = sceHttpCreateConnectionWithURL(r.tpl, q.url.c_str(), true);
    if (r.conn < 0) return "conexao " + hex(r.conn);
    r.req = sceHttpCreateRequestWithURL(r.conn, ORBIS_METHOD_GET, q.url.c_str(), 0);
    if (r.req < 0) return "requisicao " + hex(r.req);
    for (const auto &h : q.headers) sceHttpAddRequestHeader(r.req, h.first.c_str(), h.second.c_str(), 0);
    int rc = sceHttpSendRequest(r.req, nullptr, 0);
    if (rc < 0) return "envio " + hex(rc) + " (sem internet ou certificado recusado?)";
    int32_t st = 0;
    rc = sceHttpGetStatusCode(r.req, &st);
    if (rc < 0) return "status " + hex(rc);
    status = st;
    return "";
}

HttpResponse Http::get(const HttpRequest &q)
{
    HttpResponse resp;
    std::string ie;
    if (ctx_ < 0 && !init(&ie)) { resp.error = "internet do PS4 nao iniciou (" + ie + ")"; return resp; }
    Request r;
    std::string e = begin(ctx_, q, r, resp.status);
    if (!e.empty()) { resp.error = e; return resp; }
    char buf[16384];
    for (;;) {
        int n = sceHttpReadData(r.req, buf, sizeof buf);
        if (n < 0) { resp.error = "leitura " + hex(n); return resp; }
        if (n == 0) break;
        if (resp.body.size() + size_t(n) > q.maxBytes) { resp.error = "resposta maior que o limite"; resp.body.clear(); return resp; }
        resp.body.append(buf, size_t(n));
    }
    return resp;
}

std::unique_ptr<HttpStream> Http::openStream(const HttpRequest &q, std::string *error)
{
    std::string ie;
    if (ctx_ < 0 && !init(&ie)) { if (error) *error = "internet do PS4 nao iniciou (" + ie + ")"; return nullptr; }
    std::unique_ptr<Ps4Stream> s(new Ps4Stream);
    s->r.reset(new Request);
    std::string e = begin(ctx_, q, *s->r, s->code);
    if (e.empty() && (s->code < 200 || s->code >= 300)) e = "servidor respondeu HTTP " + std::to_string(s->code);
    if (!e.empty()) { if (error) *error = e; return nullptr; }
    return std::unique_ptr<HttpStream>(s.release());
}

}  // namespace ml::ps4
